package com.acme.rental.reservations;

import java.time.LocalDate;

/**
 * Checks that a vehicle class is available for every day of the rental.
 */
public class VehicleAvailabilityGuard {

    private final FleetAvailabilityRepository availability;

    public VehicleAvailabilityGuard(FleetAvailabilityRepository availability) {
        this.availability = availability;
    }

    public void assertAvailable(String locationId, String vehicleClass, LocalDate pickup, LocalDate dropoff) {
        LocalDate day = pickup;
        while (day.isBefore(dropoff)) {
            int free = availability.availableOn(locationId, vehicleClass, day);
            if (free <= 0) {
                throw new NoVehicleAvailableException(locationId, vehicleClass, day);
            }
            day = day.plusDays(1);
        }
    }
}

class NoVehicleAvailableException extends RuntimeException {
    public NoVehicleAvailableException(String loc, String cls, LocalDate day) {
        super("No " + cls + " at " + loc + " on " + day);
    }
}

