package com.acme.rental.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;

/**
 * Prices a rental from daily rate, extras and taxes.
 */
public class RentalPriceCalculator {

    private final RateTable rates;
    private final TaxTable taxes;

    public RentalPriceCalculator(RateTable rates, TaxTable taxes) {
        this.rates = rates;
        this.taxes = taxes;
    }

    public BigDecimal total(String vehicleClass, String locationId, LocalDate pickup, LocalDate dropoff, List<Extra> extras) {
        long days = ChronoUnit.DAYS.between(pickup, dropoff);
        if (days <= 0) {
            throw new IllegalArgumentException("Drop-off must be after pickup");
        }
        BigDecimal daily = rates.dailyRate(locationId, vehicleClass);
        BigDecimal base = daily.multiply(BigDecimal.valueOf(days));
        BigDecimal extrasTotal = extras.stream().map(Extra::getPrice).reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal tax = taxes.forRental(base);
        return base.add(extrasTotal).add(tax).setScale(2, RoundingMode.HALF_UP);
    }
}

