import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Reservation endpoint: licence check, availability, persistence.
 */
@RestController
public class ReservationController {

    private final LicenceValidator licenceValidator;
    private final VehicleAvailabilityGuard availability;
    private final ReservationRepository reservations;

    public ReservationController(LicenceValidator licenceValidator,
                                 VehicleAvailabilityGuard availability,
                                 ReservationRepository reservations) {
