package com.acme.rental.handover;

import java.time.Instant;

/**
 * Records vehicle checkout: mileage, fuel, and marks vehicle on rent.
 */
public class VehicleCheckoutService {

    private final ReservationRepository reservations;
    private final VehicleRepository vehicles;

    public VehicleCheckoutService(ReservationRepository reservations, VehicleRepository vehicles) {
        this.reservations = reservations;
        this.vehicles = vehicles;
    }

    public void checkout(String reservationId, int startingMileage, int fuelPercent) {
        Reservation r = reservations.require(reservationId);
        if (fuelPercent < 0 || fuelPercent > 100) {
            throw new IllegalArgumentException("Fuel percent out of range");
        }
        Vehicle v = vehicles.require(r.getVehicleId());
        v.setStatus(VehicleStatus.ON_RENT);
        v.setCurrentMileage(startingMileage);
        v.setFuelPercent(fuelPercent);
        vehicles.save(v);
        r.setCheckedOutAt(Instant.now());
        r.setStartingMileage(startingMileage);
        reservations.save(r);
    }
}

