package com.acme.rental.rules;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * Blocks high-performance vehicle rentals for inexperienced drivers.
 */
public class ExperienceRestrictionRule {

    private static final long MIN_YEARS = 2;

    private final VehicleClassRepository classes;

    public ExperienceRestrictionRule(VehicleClassRepository classes) {
        this.classes = classes;
    }

    public void assertAllowed(String vehicleClass, LocalDate licenceIssuedOn, LocalDate today) {
        VehicleClass vc = classes.require(vehicleClass);
        if (!vc.isHighPerformance()) {
            return;
        }
        long years = ChronoUnit.YEARS.between(licenceIssuedOn, today);
        if (years < MIN_YEARS) {
            throw new ExperienceRestrictionException(vehicleClass, years);
        }
    }
}

class ExperienceRestrictionException extends RuntimeException {
    public ExperienceRestrictionException(String cls, long years) {
        super("Driver with " + years + " years licence cannot rent " + cls);
    }
}

