package com.acme.rental.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Appends an audit row on every reservation status change.
 */
public class ReservationStatusAuditor {

    private final EntityManager em;

    public ReservationStatusAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String reservationId, String oldStatus, String newStatus, String operatorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            ReservationStatusEntry e = new ReservationStatusEntry();
            e.setReservationId(reservationId);
            e.setOldStatus(oldStatus);
            e.setNewStatus(newStatus);
            e.setOperatorId(operatorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

