package com.acme.rental.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises cancellation of a reservation.
 */
public class ReservationCancellationPolicy {

    private final ReservationRepository reservations;
    private final StaffDirectory staff;

    public ReservationCancellationPolicy(ReservationRepository reservations, StaffDirectory staff) {
        this.reservations = reservations;
        this.staff = staff;
    }

    public void assertMayCancel(String actorId, String reservationId) {
        Reservation r = reservations.require(reservationId);
        if (actorId.equals(r.getCustomerId())) {
            return;
        }
        if (staff.hasRole(actorId, "OPERATOR")) {
            return;
        }
        throw new AccessDeniedException("Actor " + actorId + " may not cancel " + reservationId);
    }
}

