#include <stdio.h>
#include "rental_db.h"

int write_due_back_report(const char *today, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "reservation_id,vehicle_reg,customer_name,phone\n");

    db_cursor_t *cur = NULL;
    if (db_open_due_back_cursor(&cur, today) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    due_row_t row;
    while (db_due_cursor_next(cur, &row) == DB_OK) {
        if (row.status == RESERVATION_RETURNED) continue;
        fprintf(out, "%s,%s,%s,%s\n",
                row.reservation_id, row.vehicle_reg, row.customer_name,
                row.customer_phone ? row.customer_phone : "");
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

